<span class="line"><span style="color:#ABB2BF;">    correct </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> sum</span><span style="color:#ABB2BF;">(p </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> r </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> p, r </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> zip</span><span style="color:#ABB2BF;">(predictions, references))</span></span>
